import{_ as l,o as i,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Performance Meeting 2021-04-22","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-04-22","date":"2021-04-22T00:00:00.000Z","updated":"2021-04-24T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","BlueStore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏纠正码","复制","快照","克隆","瘦分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑结构","失效域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-04-22.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-04-22.md","lastUpdated":1780460162000}'),o={name:"posts/2021/Ceph_Performance_Meeting_2021-04-22.md"};function t(n,e,s,d,p,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<p>本次会议是 Ceph 开发团队的定期会议，主要讨论了近期的工作进展、待处理的 Pull Requests（PRs）以及一些技术细节。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Requests（PRs）讨论</strong></p><ul><li>讨论了两个新的 PR，均与 o-node pinning 和 trimming 相关。一个是 Igor 提交的，另一个是 Adam 提交的，但 Adam 本周不在，因此未能深入讨论。Igor 建议对两个方案进行独立审查。</li><li>更新了关于 RGW 压缩和 roxdb 内存分配的 PR，Gabriel 的 PR 需要进一步的审查和测试。</li></ul></li><li><p><strong>技术细节讨论</strong></p><ul><li>Gabriel 讨论了在 roxdb 中进行对象计数的挑战，提出了使用估计大小和节点遍历的方法来改进进度显示。</li><li>讨论了如何从 PG map 中获取对象计数信息，以及如何改进 osd 的启动过程显示。</li></ul></li><li><p><strong>Crimson 存储优化</strong></p><ul><li>介绍了 Crimson 存储的最新进展，包括与 IBM 的合作和性能优化。目前 Crimson 在处理小随机读写方面更高效，但仍需解决多核利用率的问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>对 Igor 和 Adam 的 PR 进行独立审查，计划在下一次性能会议上进一步讨论。</li><li>Gabriel 将继续测试和改进 roldb 中的对象计数和进度显示方法。</li><li>继续推进 Crimson 存储的多核优化工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>对 Gabriel 的 PR 进行详细审查和性能测试。</li><li>继续研究和优化 Crimson 存储的多核利用率。</li><li>下一次会议将讨论 PR 的进一步审查结果和 Crimson 存储的进展。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>确认了关于 backfill 和 recovery reservations 的邮件列表讨论的澄清。</li><li>会议结束时，主持人提醒大家下周再见，并祝大家一周愉快。</li></ul><p>本次会议有效地总结了近期的工作进展，并为接下来的工作指明了方向。</p>',10)])])}const _=l(o,[["render",t]]);export{h as __pageData,_ as default};
